def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threat = 0.0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > rich_threat:
                rich_threat = opp.get('budget', 0)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_tightness < 0:
        supply_tightness = 0.0
    if supply_tightness > 1:
        supply_tightness = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.65
    elif hp <= 4:
        urgency += 0.35

    if no_water >= 2:
        urgency += 0.7
    elif no_water >= 1:
        urgency += 0.3

    urgency += 0.25 * supply_tightness
    if desperate_count >= 2:
        urgency += 0.1

    if urgency >= 1.0:
        target = max(DAILY_SALARY * 1.15, highest_prev + 4.0, avg_prev + 6.0)
    elif urgency >= 0.6:
        target = max(DAILY_SALARY * 0.82, highest_prev + 2.0, avg_prev + 3.0)
    elif urgency >= 0.3:
        target = max(DAILY_SALARY * 0.52, avg_prev * 0.72, highest_prev * 0.58)
    else:
        if highest_prev >= 140:
            target = DAILY_SALARY * 0.28
        elif highest_prev >= 90:
            target = DAILY_SALARY * 0.4
        else:
            target = max(DAILY_SALARY * 0.34, avg_prev * 0.55)

    if rich_threat < budget * 0.5 and urgency < 0.6:
        target *= 0.92

    if budget < DAILY_SALARY * 1.2:
        target = min(target, budget * 0.72)
    elif budget < DAILY_SALARY * 2.5 and urgency < 0.6:
        target = min(target, DAILY_SALARY * 0.7)

    if hp >= 8 and no_water == 0 and supply >= 21:
        target = min(target, DAILY_SALARY * 0.38)

    bid = min(budget, max(0.0, target))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from alive opponents; use max as proxy for who is pressuring.
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    pressure = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: higher supply reduces need to overbid.
    # Normalize supply to [0,1]
    norm_supply = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        norm_supply = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if norm_supply < 0.0:
            norm_supply = 0.0
        if norm_supply > 1.0:
            norm_supply = 1.0

    # If others bid extremely high yesterday, they likely will again; avoid being the one starved.
    # Use HP/no_water_days to decide aggressiveness.
    if pressure >= DAILY_SALARY * 1.0:
        # Survivors likely outbid; we only need enough to secure water consistently.
        base = DAILY_SALARY * (0.45 + 0.25 * (1.0 - norm_supply))
        if my_hp <= 2 or my_no_water_days >= 1:
            base = DAILY_SALARY * 0.75
    elif pressure >= DAILY_SALARY * 0.6:
        base = DAILY_SALARY * (0.40 + 0.20 * (1.0 - norm_supply))
        if my_hp <= 2 or my_no_water_days >= 1:
            base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * (0.35 + 0.15 * (1.0 - norm_supply))
        if my_hp <= 2 or my_no_water_days >= 1:
            base = DAILY_SALARY * 0.55

    # Slight day-based ramp to prevent late collapse.
    if day >= 7:
        base *= 1.08

    # Convert base into a bid with a small competitive premium.
    # If pressure exists, try to be near but not exceed it drastically.
    bid = base
    if pressure > 0.0:
        # Target: either just above a fraction of pressure or base whichever is higher.
        target = pressure * 0.55
        if target > bid:
            bid = target
        # Cap premium
        if bid > pressure * 0.85:
            bid = pressure * 0.85

    # Final clamp by budget and a safety floor.
    if my_budget <= 0.0:
        return 0.0

    # Ensure we don't bid more than budget.
    if bid > my_budget:
        bid = my_budget

    # If budget is tight, still bid something proportional.
    min_bid = 0.0
    if my_budget > 0.0:
        min_bid = min(DAILY_SALARY * 0.15, my_budget)

    if bid < min_bid:
        bid = min_bid

    return float(bid)
